styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  column-gap: var(--g-gap);

  position: relative;
  min-height: calc( var(--vh,1vh) * 800 );
}

section[data-skill-hub] .percent {
  position: absolute;
  top: 50%;
  left: 50%;
}

section[data-skill-hub] .text {
  grid-column-start: 1;
  grid-column-end: 7;
  align-self: start;

  position: sticky;
  top: 0;
  min-height: calc( var(--vh,1vh) * 100 );
  display: flex;
  align-items: center;
}
section[data-skill-hub] .indent {
  display: inline-flex;
  width: calc((2 / 6) * (var(--vw, 1vw) * 100 - var(--g-margin) * 2));
}
section[data-skill-hub] .indent::before {
  letter-spacing: initial;
  content: 'Scroll: ' attr(data-val-pct) '%';
  font-size: var(--m);
  font-feature-settings: 'ss03', 'ss14';
}
section[data-skill-hub] .-highlight {
  color: #a399a8;
}
section[data-skill-hub] .-s-word {
  --word-turn: calc( (var(--word-index) - 3) / var(--word-global-total) );
  --word-step: calc( 1 / var(--word-global-total) );
  --word-progress: clamp( 0, calc( (var(--progress) - var(--word-turn)) / var(--word-step) ), 1 );

  transform: translate3d(0, calc(100% - var(--word-progress) * 100% ), 0);
  clip-path: inset(-15% 0 calc( 115% - var(--word-progress) * 130% ) 0);
}

@media (min-width: 1024px) {
  section[data-skill-hub] .-w {
    grid-template-columns: repeat(14, 1fr);
  }
  section[data-skill-hub] .text {
    grid-column-start: 3;
    grid-column-end: 13;
  }
  section[data-skill-hub] .indent {
    width: calc((2 / 14) * (var(--vw, 1vw) * 100 - var(--g-margin) * 2));
  }
  section[data-skill-hub] .break {
    display: block;
    width: 100%;
    height: var(--h4);
  }
}
